def valve_code(text: str):
    """'15BV' -> ('15', 'BV'); '9-SRV-7101' -> ('', 'SRV'); otherwise None."""
    t = normalize_tag(text)
    m = _CODE_RE.match(t.replace("-", ""))
    if m:
        return m.group(1) or "", m.group(2)
    p = parse_tag(t)
    if p and p["letters"] in VALVE_CODES:
        return "", p["letters"]
    return None
